// Iterative

func gcd(a: Int, b: Int) -> Int {

    var a = abs(a)
    var b = abs(b)

    if (b > a) { swap(&a, &b) }

    while (b > 0) { (a, b) = (b, a % b) }

    return a
}

// Recursive

func gcdr (a: Int, b: Int) -> Int {

    var a = abs(a)
    var b = abs(b)

    if (b > a) { swap(&a, &b) }

    return gcd_rec(a,b)
}


private func gcd_rec(a: Int, b: Int) -> Int {

    return b == 0 ? a : gcd_rec(b, a % b)
}


