import java.util.ArrayList;
import java.util.List;

public final class Combinations {

	public static void main(String[] args) {		
		System.out.println(createCombinations(List.of( 0, 1, 2, 3, 4 ), 3));
		System.out.println(createCombinations(List.of( "Crosby", "Nash", "Stills", "Young" ), 3));
	}

	private static <T> List<List<T>> createCombinations(List<T> elements, int k) {
		List<List<T>> combinations = new ArrayList<List<T>>();
		createCombinations(elements, k, new ArrayList<T>(), combinations, 0);
		return combinations;
	}

	private static <T> void createCombinations(
			List<T> elements, int k, List<T> accumulator, List<List<T>> combinations, int index) {
		if ( accumulator.size() == k ) {
		    combinations.addFirst( new ArrayList<T>(accumulator) );
		} else if ( k - accumulator.size() <= elements.size() - index ) {
		    createCombinations(elements, k, accumulator, combinations, index + 1);
		    accumulator.add(elements.get(index));
		    createCombinations(elements, k, accumulator, combinations, index + 1);
		    accumulator.removeLast();
		}
	}

}

using System;
using System.Collections.Generic;

public class Program
{
    public static IEnumerable<int[]> Combinations(int m, int n)
    {
            int[] result = new int[m];
            Stack<int> stack = new Stack<int>();
            stack.Push(0);

            while (stack.Count > 0)
           {
                int index = stack.Count - 1;
                int value = stack.Pop();

                while (value < n) 
               {
                    result[index++] = ++value;
                    stack.Push(value);

                    if (index == m) 
                    {
                        yield return result;
                        break;
                    }
                }
            }
    }

    static void Main()
    {
        foreach (int[] c in Combinations(3, 5))
        {
            Console.WriteLine(string.Join(",", c));
            Console.WriteLine();
        }
    }
}

func addCombo(prevCombo: [Int], var pivotList: [Int]) -> [([Int], [Int])] {

  return (0..<pivotList.count)
    .map {
      _ -> ([Int], [Int]) in
      (prevCombo + [pivotList.removeAtIndex(0)], pivotList)
    }
}
func combosOfLength(n: Int, m: Int) -> Int {

  return [Int](1...m)
    .reduce([([Int](), [Int](0..<n))]) {
      (accum, _) in
      accum.flatMap(addCombo)
    }.map {
      $0.0
    }
}

println(combosOfLength(5, 3))

class Combinations(val m: Int, val n: Int) {
    private val combination = IntArray(m)

    init {
        generate(0)
    }

    private fun generate(k: Int) {
        if (k >= m) {
            for (i in 0 until m) print("${combination[i]} ")
            println()
        }
        else {
            for (j in 0 until n)
                if (k == 0 || j > combination[k - 1]) {
                    combination[k] = j
                    generate(k + 1)
                }
        }
    }
}

